// R2 drift guard: every fixture renders the same here as through VG's own
// HybridMarkdownRenderer. Expected HTML is generated BY VG — regenerate with
// scripts/vg-parity/README.md after re-porting, never by hand.
import { describe, it, expect } from 'vitest';
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { renderLibraryMarkdown } from '../library';
import { normaliseForParity } from './parity';

const dir = join(__dirname, 'fixtures');
const expected: Record<string, string> = JSON.parse(readFileSync(join(dir, 'vg-expected.json'), 'utf8'));
const fixtures = readdirSync(dir).filter((f) => f.endsWith('.md')).sort();

describe('VG renderer parity', () => {
	it('has VG output for every fixture', () => {
		expect(Object.keys(expected).sort()).toEqual(fixtures);
	});
	for (const f of fixtures) {
		it(f, () => {
			const md = readFileSync(join(dir, f), 'utf8');
			const mine = renderLibraryMarkdown(md, { math: f.includes('papers--') });
			expect(normaliseForParity(mine)).toBe(normaliseForParity(expected[f]));
		});
	}
});
